123	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
124	        }
125	        if (!on.equals(claim.getDate())) {
126	            people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
127	        }
128	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects);
129	        Rollup.Figures before = rollup.figures(sheetId);
130	        claim.setAmount(amount);
131	        claim.setCorrects(corrects);
132	        claim.setCorrectsDate(correctsDate);
133	        claim.setDate(on);
134	        claim.setNote(note == null ? "" : note);
135	        claims.flush();
136	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
137	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
