178	                next = ClaimStatus.PENDING;
179	            }
180	        }
181	        claim.setStatus(next);
182	        log(sheetId, user, claim, owner);
183	        claims.flush();
184	        String person = owner == null ? "" : owner.getName();
185	        String event = switch (next) {
186	            case OPEN -> "CLAIM_OPENED";
