197	    /**
198	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
199	     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
200	     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim dated inside a closed
201	     * period is refused and nothing changes. Returns the person it belongs to.
202	     */
203	    @Transactional
204	    public long defer(String sheetId, String user, long claimId, LocalDate until) {
205	        Claim claim = claim(sheetId, claimId);
206	        if (claim.getStatus() != ClaimStatus.OPEN) {
207	            throw new ResponseStatusException(HttpStatus.CONFLICT,
208	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
209	        }
210	        LocalDate today = sheets.today(sheetId);
211	        if (!until.isAfter(today)) {
212	            throw new ResponseStatusException(HttpStatus.CONFLICT,
213	                    "A claim can only be deferred to a date after the sheet's today (" + today + ")");
214	        }
215	        Rollup.Figures before = rollup.figures(sheetId);
216	        claim.setDeferredUntil(until);
217	        claims.flush();
218	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
219	        events.publishEvent(new ClaimDeferred(sheetId, user, person, claim.getAmount(), claim.getDate(),
