225	    /**
226	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
227	     * Only a steward approves, never the user who opened the claim; a claim not PENDING or dated inside a
228	     * closed period is refused and nothing changes. Returns the person it belongs to.
229	     */
230	    @Transactional
231	    public long approve(String sheetId, String user, long claimId) {
232	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
233	        if (user.equals(claim.getOpenedBy())) {
234	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
235	        }
236	        Rollup.Figures before = rollup.figures(sheetId);
237	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
238	        BigDecimal fixed = dueNow(sheetId, claim, owner);
239	        claim.setSettledDue(fixed);
240	        claim.setStatus(ClaimStatus.SETTLED);
241	        log(sheetId, user, claim, owner);
242	        claims.flush();
243	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
244	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
245	        rollup.changed(sheetId, user, before);
246	        return claim.getPersonId();
247	    }
